t.script:
                let currentTab = 0;
                const tabs = document.querySelectorAll('.tab-content');
                const tabButtons = document.querySelectorAll('.tab-button');
                const prevBtn = document.getElementById('prevBtn');
                const nextBtn = document.getElementById('nextBtn');

                function showTab(n) {
                tabs.forEach((tab, index) => {
                tab.classList.toggle('active', index === n);
                });
                tabButtons.forEach((button, index) => {
                button.classList.toggle('active', index === n);
                });
                prevBtn.disabled = n === 0;
                nextBtn.textContent = n === tabs.length - 1 ? 'Submit' : 'Next';
                validateTab();
                }

                function changeTab(step) {
                if (step === 1 & !validateTab()) return;
                currentTab += step;
                if (currentTab >= tabs.length) {
                document.getElementById('stu_adm_form').submit();
                return;
                }
                showTab(currentTab);
                }

                function validateTab() {
                const currentInputs = tabs[currentTab].querySelectorAll('input[required], select[required]');
                const allValid = Array.from(currentInputs).every(input => input.checkValidity());
                nextBtn.disabled = !allValid;
                nextBtn.classList.toggle('bg-blue-500', allValid);
                nextBtn.classList.toggle('bg-gray-300', !allValid);
                return allValid;
                }

                document.querySelectorAll('input, select').forEach(input => {
                input.addEventListener('input', validateTab);
                input.addEventListener('change', validateTab);
                });

                document.addEventListener('DOMContentLoaded', () => {
                showTab(currentTab);
                });

                // 
                $(document).ready(function(){
                // CNIC number format: 99999-9999999-9
                $("#stu_cnic, #par1_cnic, #par2_cnic").inputmask("99999-9999999-9");

                // Phone number format: 9999-9999999
                $("#stu_phone, #par1_phone, #par2_phone, #ec1_phone, #ec2_phone").inputmask("9999-9999999");
                });

                // 
                flatpickr(["#stu_dob", "#par1_dob", "#par2_dob"], {
                dateFormat: "d/m/Y",
                allowInput: true
                });
